head.b:skin:
*{
margin:0;
padding:0;
box-sizing:border-box;
}

:root{
--primary:#5b5ce2;
--primary-light:#7c7ff3;
--dark:#111827;
--muted:#6b7280;
--light-gray:#f3f4f6;
--border:#e5e7eb;
--bg:#f9fafb;
}

body{
font-family:'Poppins',sans-serif;
background:var(--bg);
color:var(--dark);
}

.header{
padding:18px 20px;
background:#ffffff;
position:sticky;
top:0;
z-index:999;
border-bottom:1px solid var(--border);
}

.logo{
font-size:22px;
font-weight:700;
text-align:center;
color:var(--primary);
}

.hero-section{
padding:12px 20px;
text-align:center;
background:#ffffff;
border-bottom:1px solid var(--border);
}

.hero-badge{
display:inline-flex;
align-items:center;
gap:8px;
background:#ffffff;
border:1px solid var(--border);
padding:8px 14px;
border-radius:999px;
font-size:11px;
font-weight:600;
color:var(--primary);
margin-bottom:14px;
}

.badge-dot{
width:7px;
height:7px;
border-radius:50%;
background:var(--primary);
}

.hero-title{
font-size:34px;
line-height:1.1;
font-weight:800;
letter-spacing:-1px;
max-width:900px;
margin:0 auto 12px;
}

.hero-description{
max-width:700px;
margin:0 auto 18px;
font-size:14px;
line-height:1.6;
color:var(--muted);
}

.hero-feature-row{
display:flex;
justify-content:center;
gap:10px;
flex-wrap:wrap;
}

.hero-feature{
padding:7px 14px;
border:1px solid var(--border);
border-radius:20px;
background:#ffffff;
font-size:11px;
font-weight:600;
}

.container{
max-width:1450px;
margin:0 auto;
padding:28px 18px;
}

.workspace-layout{
display:grid;
grid-template-columns:
minmax(360px,420px)
minmax(900px,1fr);
gap:28px;
align-items:start;
}

.editor-panel{
width:420px;
flex-shrink:0;
}

.preview-panel{
flex:1;
position:sticky;
top:24px;
align-self:flex-start;
will-change:transform;
transform:translateZ(0);
backface-visibility:hidden;
}

.card{
background:#ffffff;
padding:26px;
border-radius:16px;
border:1px solid var(--border);
box-shadow:0 2px 8px rgba(0,0,0,.03);
margin-bottom:24px;
}

.card-title{
font-size:18px;
font-weight:700;
margin-bottom:20px;
display:flex;
align-items:center;
gap:10px;
}

.card-title-icon{
width:5px;
height:22px;
background:var(--primary);
border-radius:4px;
}

.form-group{
margin-bottom:16px;
}

label{
display:block;
margin-bottom:6px;
font-size:13px;
font-weight:600;
}

input,
textarea{
width:100%;
padding:11px 13px;
border-radius:10px;
border:1px solid var(--border);
font-family:'Poppins',sans-serif;
font-size:13px;
background:#ffffff;
}

textarea{
min-height:100px;
resize:vertical;
}

.helper{
font-size:11px;
color:var(--muted);
margin-top:5px;
line-height:1.5;
}

.btn-group{
display:flex;
gap:10px;
flex-wrap:wrap;
margin-top:14px;
}

.btn{
padding:11px 16px;
border:none;
border-radius:10px;
cursor:pointer;
font-family:'Poppins',sans-serif;
font-size:13px;
font-weight:600;
}

.btn-primary{
background:var(--primary);
color:#ffffff;
}

.btn-secondary{
background:#ffffff;
border:1px solid var(--border);
}

.template-grid{
display:grid;
grid-template-columns:1fr 1fr;
gap:12px;
margin-top:16px;
}

.template-card{
border:2px solid var(--border);
border-radius:12px;
padding:8px;
cursor:pointer;
background:#ffffff;
}

.template-card.active{
border-color:var(--primary);
}

.template-card img{
width:100%;
height:100px;
object-fit:cover;
border-radius:8px;
display:block;
}

.template-card span{
display:block;
text-align:center;
margin-top:8px;
font-size:12px;
font-weight:600;
}

#headerPreview{
margin-top:12px;
border-radius:12px;
border:2px dashed var(--border);
min-height:120px;
display:flex;
align-items:center;
justify-content:center;
padding:14px;
background:var(--light-gray);
overflow:hidden;
}

#headerPreview img{
max-width:100%;
max-height:120px;
object-fit:contain;
}

.preview-card{
background:#ffffff;
padding:12px;
border-radius:24px;
border:1px solid rgba(229,231,235,.85);
box-shadow:
0 12px 36px rgba(15,23,42,.06),
0 2px 8px rgba(15,23,42,.04);
overflow:auto;
}

.preview-header{
margin-bottom:18px;
}

.preview-title{
font-size:20px;
font-weight:700;
margin-bottom:6px;
}

.preview-meta{
font-size:12px;
color:var(--muted);
display:flex;
gap:12px;
}

.canvas-stage{
padding:10px;
background:linear-gradient(135deg,#f3f4f6 0%,#ffffff 100%);
border:1px solid var(--border);
border-radius:12px;
margin-bottom:20px;
}

.canvas-wrap{
position:relative;
width:100%;
aspect-ratio:1.414/1;

display:flex;
align-items:center;
justify-content:center;

background:#ffffff;
border-radius:10px;
overflow:hidden;

box-shadow:0 8px 30px rgba(0,0,0,.08);
}

#certificateCanvas{
width:100%;
height:auto;
display:block;
border-radius:18px;

image-rendering:auto;
transform:translateZ(0);
backface-visibility:hidden;

max-width:100%;
object-fit:contain;
}

.footer{
padding:34px 20px;
text-align:center;
border-top:1px solid var(--border);
background:#ffffff;
margin-top:40px;
}

.footer-brand{
display:block;
font-size:18px;
font-weight:700;
margin-bottom:6px;
}

.footer-text{
font-size:12px;
color:var(--muted);
}



.footer-links{
display:flex;
justify-content:center;
gap:18px;
margin-top:14px;
flex-wrap:wrap;
}

.footer-links a{
text-decoration:none;
font-size:13px;
font-weight:500;
color:var(--muted);
transition:.2s;
}

.footer-links a:hover{
color:var(--primary);
}

.adsense-slot{
margin:28px auto;
padding:12px;
background:#ffffff;
border-radius:14px;
border:1px dashed var(--border);
text-align:center;
max-width:1450px;
}

.modal-overlay{
position:fixed;
inset:0;
background:rgba(0,0,0,.55);
display:none;
z-index:9998;
backdrop-filter:blur(4px);
}

.modal-box{
position:fixed;
top:50%;
left:50%;
transform:translate(-50%,-50%);
width:min(92%,720px);
background:#ffffff;
border-radius:20px;
padding:28px;
display:none;
z-index:9999;
box-shadow:0 20px 70px rgba(0,0,0,.2);
max-height:85vh;
overflow-y:auto;
}

.modal-header{
display:flex;
justify-content:space-between;
align-items:center;
margin-bottom:20px;
}

.modal-header h2{
font-size:24px;
font-weight:700;
}

.modal-close{
border:none;
background:none;
font-size:32px;
cursor:pointer;
color:#6b7280;
}

.modal-content p,
.modal-content li{
font-size:14px;
line-height:1.9;
color:#4b5563;
margin-bottom:14px;
}

.seo-content{
max-width:1180px;
margin:54px auto 0;
padding:54px;
border-radius:30px;
background:
linear-gradient(
180deg,
#ffffff 0%,
#fafbff 100%
);
border:1px solid rgba(229,231,235,.7);
box-shadow:
0 10px 40px rgba(15,23,42,.04),
0 2px 10px rgba(15,23,42,.03);
position:relative;
overflow:hidden;
}

.seo-content::before{
content:'';
position:absolute;
top:-120px;
right:-120px;
width:260px;
height:260px;
border-radius:50%;
background:
radial-gradient(
circle,
rgba(91,92,226,.10) 0%,
rgba(91,92,226,0) 72%
);
pointer-events:none;
}

.seo-content h2{
font-size:48px;
line-height:1.05;
font-weight:800;
letter-spacing:-2px;
color:#111827;
max-width:760px;
margin-bottom:22px;
position:relative;
z-index:2;
}

.seo-content > p{
font-size:17px;
line-height:1.9;
color:#6b7280;
max-width:780px;
margin-bottom:42px;
position:relative;
z-index:2;
}

.seo-content h3{
font-size:24px;
font-weight:700;
color:#111827;
margin-bottom:22px;
margin-top:44px;
display:flex;
align-items:center;
gap:14px;
position:relative;
z-index:2;
}

.seo-content h3::before{
content:'';
width:6px;
height:24px;
border-radius:999px;
background:
linear-gradient(
180deg,
#5b5ce2,
#7c7ff3
);
display:block;
}

.seo-content ul{
display:grid;
grid-template-columns:
repeat(auto-fit,minmax(220px,1fr));
gap:18px;
list-style:none;
padding:0;
margin:0 0 10px;
position:relative;
z-index:2;
}

.seo-content li{
background:#ffffff;
border:1px solid #eef1f5;
border-radius:18px;
padding:22px 20px;
font-size:15px;
font-weight:600;
color:#374151;
box-shadow:
0 4px 14px rgba(0,0,0,.03);
transition:
transform .25s ease,
box-shadow .25s ease,
border-color .25s ease;
}

.seo-content li:hover{
transform:translateY(-4px);
border-color:rgba(91,92,226,.18);
box-shadow:
0 12px 28px rgba(91,92,226,.08);
}

.seo-content strong{
color:#111827;
}

.seo-content p{
font-size:15px;
line-height:1.95;
color:#6b7280;
max-width:900px;
position:relative;
z-index:2;
}

@media(max-width:768px){

.seo-content{
padding:34px 24px;
border-radius:24px;
margin-top:42px;
}

.seo-content h2{
font-size:34px;
letter-spacing:-1px;
}

.seo-content > p{
font-size:15px;
margin-bottom:30px;
}

.seo-content h3{
font-size:20px;
margin-top:34px;
}

.seo-content ul{
grid-template-columns:1fr;
gap:14px;
}

.seo-content li{
padding:18px;
font-size:14px;
}

}
.scroll-indicator{
position:fixed;
bottom:28px;
right:28px;
display:flex;
align-items:center;
gap:12px;
padding:12px 16px;
background:rgba(255,255,255,.92);
backdrop-filter:blur(14px);
border:1px solid rgba(229,231,235,.9);
border-radius:999px;
box-shadow:
0 10px 30px rgba(15,23,42,.08),
0 2px 8px rgba(15,23,42,.05);
z-index:9997;
transition:
opacity .35s ease,
transform .35s ease;
animation:floatHint 3s ease-in-out infinite;
}

.scroll-indicator.hidden{
opacity:0;
transform:translateY(20px);
pointer-events:none;
}

.scroll-indicator span{
font-size:13px;
font-weight:600;
color:#374151;
white-space:nowrap;
}

.scroll-mouse{
width:24px;
height:38px;
border:2px solid #5b5ce2;
border-radius:20px;
display:flex;
justify-content:center;
padding-top:6px;
background:#ffffff;
}

.scroll-wheel{
width:4px;
height:8px;
border-radius:999px;
background:#5b5ce2;
animation:scrollWheel 1.6s infinite;
}

@keyframes scrollWheel{

0%{
opacity:1;
transform:translateY(0);
}

100%{
opacity:0;
transform:translateY(10px);
}

}

@keyframes floatHint{

0%{
transform:translateY(0);
}

50%{
transform:translateY(-4px);
}

100%{
transform:translateY(0);
}

}

@media(max-width:768px){

.scroll-indicator{
bottom:18px;
right:18px;
padding:10px 14px;
}

.scroll-indicator span{
font-size:12px;
}

}

@media(max-width:1200px){

.workspace-layout{
grid-template-columns:1fr;
}

.editor-panel,
.preview-panel{
width:100%;
max-width:100%;
position:relative;
top:0;
}

.preview-panel{
position:relative;
}

}

@media(max-width:768px){

.hero-title{
font-size:32px;
}

.container{
padding:20px 14px;
}

.card{
padding:22px;
}

.template-grid{
grid-template-columns:1fr;
}


}
@media(max-width:768px){


}

body.script:
//

const EXPORT_DPI = 300;

const BASE_WIDTH = 1554;
const BASE_HEIGHT = 1100;

const EXPORT_WIDTH = 3508;
const EXPORT_HEIGHT = 2480;

let headerImage = new Image();

headerImage.crossOrigin = 'anonymous';

headerImage.src =
'https://raw.githubusercontent.com/manniyil/certifystudio/refs/heads/main/cert-header-psd.svg';
headerImage.onload = function(){

const preview =
document.getElementById('headerPreview');

if(preview){

preview.innerHTML =
'<img src="' + headerImage.src + '">';

}

updateCertificate();

};
let sealImage = null;
let leftSignatureImage = null;
let rightSignatureImage = null;

const backgroundTemplates = [
'https://cdn.jsdelivr.net/gh/manniyil/certifystudio/blue.webp',
'https://cdn.jsdelivr.net/gh/manniyil/certifystudio/gold.webp'
];

let backgroundImage = new Image();

backgroundImage.crossOrigin = 'anonymous';

backgroundImage.src = backgroundTemplates[0];

function selectBackground(index,element){

backgroundImage = new Image();

backgroundImage.crossOrigin = 'anonymous';

backgroundImage.onload = function(){

updateCertificate();

};

backgroundImage.src = backgroundTemplates[index];

document
.querySelectorAll('.template-card')
.forEach(function(card){

card.classList.remove('active');

});

element.classList.add('active');

}

function handleCustomBackgroundUpload(event){

const file = event.target.files[0];

if(!file)return;

const reader = new FileReader();

reader.onload = function(e){

backgroundImage = new Image();

backgroundImage.crossOrigin = 'anonymous';

backgroundImage.onload = function(){

document
.querySelectorAll('.template-card')
.forEach(function(card){

card.classList.remove('active');

});

updateCertificate();

};

backgroundImage.src = e.target.result;

};

reader.readAsDataURL(file);

}

function resetDefaultBackground(){

backgroundImage = new Image();

backgroundImage.crossOrigin = 'anonymous';

backgroundImage.onload = updateCertificate;

backgroundImage.src = backgroundTemplates[0];

document
.querySelectorAll('.template-card')
.forEach(function(card){

card.classList.remove('active');

});

document
.querySelector('.template-card')
.classList.add('active');

}



function initializeCanvas(){

const canvas =
document.getElementById('certificateCanvas');

const ctx =
canvas.getContext('2d');

canvas.width = BASE_WIDTH;
canvas.height = BASE_HEIGHT;

ctx.imageSmoothingEnabled = true;
ctx.imageSmoothingQuality = 'high';

return {
canvas,
ctx,
width:BASE_WIDTH,
height:BASE_HEIGHT
};

}

function createHighResCanvas(){

const exportCanvas = document.createElement('canvas');

exportCanvas.width = EXPORT_WIDTH;
exportCanvas.height = EXPORT_HEIGHT;

const exportCtx = exportCanvas.getContext('2d');

exportCtx.imageSmoothingEnabled = true;
exportCtx.imageSmoothingQuality = 'high';

renderCertificate(
exportCtx,
EXPORT_WIDTH,
EXPORT_HEIGHT,
EXPORT_WIDTH / BASE_WIDTH
);

return exportCanvas;

}

function wrapText(ctx,text,x,y,maxWidth,lineHeight){

const words = text.split(' ');
let line = '';

for(let n=0;n<words.length;n++){

const testLine = line + words[n] + ' ';

const metrics = ctx.measureText(testLine);

if(metrics.width > maxWidth && n > 0){

ctx.fillText(line,x,y);

line = words[n] + ' ';

y += lineHeight;

}else{

line = testLine;

}

}

ctx.fillText(line,x,y);

return y;

}

function handleHeaderUpload(event){

const file = event.target.files[0];

if(!file)return;

const reader = new FileReader();

reader.onload = function(e){

headerImage = new Image();

headerImage.onload = function(){

const preview =
document.getElementById('headerPreview');

preview.innerHTML = '';

const img =
document.createElement('img');

img.src = e.target.result;

preview.appendChild(img);

updateCertificate();

};

headerImage.src = e.target.result;

};

reader.readAsDataURL(file);

}

function handleSealUpload(event){

const file = event.target.files[0];

if(!file)return;

const reader = new FileReader();

reader.onload = function(e){

sealImage = new Image();

sealImage.onload = updateCertificate;

sealImage.src = e.target.result;

};

reader.readAsDataURL(file);

}

function handleLeftSignatureUpload(event){

const file = event.target.files[0];

if(!file)return;

const reader = new FileReader();

reader.onload = function(e){

leftSignatureImage = new Image();

leftSignatureImage.onload = updateCertificate;

leftSignatureImage.src = e.target.result;

};

reader.readAsDataURL(file);

}

function handleRightSignatureUpload(event){

const file = event.target.files[0];

if(!file)return;

const reader = new FileReader();

reader.onload = function(e){

rightSignatureImage = new Image();

rightSignatureImage.onload = updateCertificate;

rightSignatureImage.src = e.target.result;

};

reader.readAsDataURL(file);

}

function removeHeaderImage(){

headerImage = new Image();

headerImage.crossOrigin = 'anonymous';

headerImage.onload = updateCertificate;

headerImage.src =
'https://i.postimg.cc/0jjPXVVx/header-certificate.png';

document.getElementById('headerPreview').innerHTML = '';

document.getElementById('headerImageUpload').value = '';

}

function removeLeftSignature(){

leftSignatureImage = null;

document.getElementById('leftSignatureUpload').value = '';

updateCertificate();

}

function removeRightSignature(){

rightSignatureImage = null;

document.getElementById('rightSignatureUpload').value = '';

updateCertificate();

}

function removeSeal(){

sealImage = null;

document.getElementById('sealUpload').value = '';

updateCertificate();

}

function renderCertificate(ctx,width,height,scale){

ctx.clearRect(0,0,width,height);

if(backgroundImage.complete){

ctx.drawImage(backgroundImage,0,0,width,height);

}else{

ctx.fillStyle = '#ffffff';
ctx.fillRect(0,0,width,height);

}

let currentY = 90 * scale;

ctx.textAlign = 'center';

const headerHeight = 170 * scale;

if(headerImage){

const imgWidth = 950 * scale;

ctx.drawImage(
  headerImage,
  (width - imgWidth) / 2,
  currentY,
  imgWidth,
  headerHeight
);

}

currentY += headerHeight + (30 * scale);
ctx.fillStyle = '#111827';

ctx.font = `${700 * scale/scale} ${62 * scale}px Cormorant Garamond`;

currentY = wrapText(
ctx,
document.getElementById('certTitle').value,
width / 2,
currentY,
width - (320 * scale),
72 * scale
);

currentY += 70 * scale;

ctx.font = `${500 * scale/scale} ${24 * scale}px Poppins`;

ctx.fillText(
'This certificate is proudly presented to',
width / 2,
currentY
);

currentY += 110 * scale;

ctx.fillStyle = '#2f3e7a';

ctx.font = `${400 * scale/scale} ${92 * scale}px Great Vibes`;

currentY = wrapText(
ctx,
document.getElementById('recipientName').value,
width / 2,
currentY,
width - (260 * scale),
92 * scale
);

currentY += 92 * scale;

ctx.fillStyle = '#111827';

ctx.font = `${500 * scale/scale} ${24 * scale}px Poppins`;

ctx.fillText(
document.getElementById('achievementPrefix').value,
width / 2,
currentY
);

currentY += 70 * scale;

ctx.fillStyle = '#1e3a8a';

ctx.font = `${700 * scale/scale} ${42 * scale}px Poppins`;

currentY = wrapText(
ctx,
document.getElementById('courseTitle').value,
width / 2,
currentY,
width - (320 * scale),
56 * scale
);

currentY += 50 * scale;

ctx.fillStyle = '#4b5563';

ctx.font = `${400 * scale/scale} ${20 * scale}px Poppins`;

wrapText(
ctx,
document.getElementById('certDescription').value,
width / 2,
currentY,
width - (500 * scale),
40 * scale
);
const signatureY = height - (260 * scale);

const leftX = width * 0.22;
const centerX = width * 0.5;
const rightX = width * 0.78;

ctx.strokeStyle = '#9ca3af';
ctx.lineWidth = 2 * scale;

ctx.beginPath();
ctx.moveTo(leftX - (110 * scale), signatureY);
ctx.lineTo(leftX + (110 * scale), signatureY);
ctx.stroke();

ctx.beginPath();
ctx.moveTo(rightX - (110 * scale), signatureY);
ctx.lineTo(rightX + (110 * scale), signatureY);
ctx.stroke();

if(leftSignatureImage){

ctx.drawImage(
leftSignatureImage,
leftX - (90 * scale),
signatureY - (90 * scale),
180 * scale,
70 * scale
);

}

if(rightSignatureImage){

ctx.drawImage(
rightSignatureImage,
rightX - (90 * scale),
signatureY - (90 * scale),
180 * scale,
70 * scale
);

}

if(sealImage){

ctx.globalAlpha = 0.95;

ctx.drawImage(
sealImage,
centerX - (80 * scale),
signatureY - (70 * scale),
160 * scale,
160 * scale
);

ctx.globalAlpha = 1;

}

ctx.fillStyle = '#111827';

ctx.font = `${600} ${20 * scale}px Poppins`;

ctx.fillText(
document.getElementById('signatoryLeft').value,
leftX,
signatureY + (34 * scale)
);

ctx.fillText(
document.getElementById('signatoryRight').value,
rightX,
signatureY + (34 * scale)
);

ctx.fillStyle = '#6b7280';

ctx.font = `${400} ${16 * scale}px Poppins`;

ctx.fillText(
document.getElementById('designationLeft').value,
leftX,
signatureY + (62 * scale)
);

ctx.fillText(
document.getElementById('designationRight').value,
rightX,
signatureY + (62 * scale)
);
}


function updateCertificate(){

const setup = initializeCanvas();


renderCertificate(
setup.ctx,
setup.width,
setup.height,
1
);

}



function downloadCertificatePNG(){

updateCertificate();

const canvas = createHighResCanvas();

const link = document.createElement('a');

link.download = 'certify-studio-certificate.png';

link.href = canvas.toDataURL('image/png');

link.click();

}

async function downloadCertificatePDF(){

updateCertificate();

const canvas = createHighResCanvas();

const imageData = canvas.toDataURL('image/png');

const { jsPDF } = window.jspdf;

const pdf = new jsPDF({
orientation:'landscape',
unit:'mm',
format:'a4'
});

pdf.addImage(
imageData,
'PNG',
0,
0,
297,
210,
'',
'FAST'
);

pdf.save('certify-studio-certificate.pdf');

}

async function downloadBulkCertificates(){

const bulkInput =
document.getElementById('bulkNames').value;

if(!bulkInput.trim()){

alert('Please enter names');

return;

}

const names =
bulkInput
.split('\n')
.map(name => name.trim())
.filter(Boolean);

const { jsPDF } =
window.jspdf;

const pdf =
new jsPDF({
orientation:'landscape',
unit:'mm',
format:'a4'
});

const originalName =
document.getElementById('recipientName').value;

for(let i = 0; i < names.length; i++){

document.getElementById('recipientName').value =
names[i];

updateCertificate();

await new Promise(resolve => setTimeout(resolve,200));

const canvas = createHighResCanvas();

const imageData = canvas.toDataURL('image/png');

if(i > 0){

pdf.addPage('a4','landscape');

}

pdf.addImage(
imageData,
'PNG',
0,
0,
297,
210,
'',
'FAST'
);

}

document.getElementById('recipientName').value =
originalName;

updateCertificate();

pdf.save('certify-studio-bulk-certificates.pdf');

}

function printCertificate(){

const canvas = createHighResCanvas();

const dataUrl = canvas.toDataURL('image/png');

const printWindow = window.open('','_blank');

printWindow.document.write(
'<!DOCTYPE html><html><head><title>Print</title><style>html,body{margin:0;padding:0;background:#fff;}img{width:100%;height:auto;}@page{size:A4 landscape;margin:0;}<\/style><\/head><body><img src="'+dataUrl+'"/><\/body><\/html>'
);

printWindow.document.close();

setTimeout(function(){

printWindow.focus();
printWindow.print();

},600);

}

window.addEventListener('load',function(){

headerImage.onload = function(){

updateCertificate();

};

updateCertificate();

});


function openModal(id){

document.getElementById('modalOverlay').style.display='block';

document.getElementById(id).style.display='block';

document.body.style.overflow='hidden';

}

function closeModal(){

document.getElementById('modalOverlay').style.display='none';

document.querySelectorAll('.modal-box').forEach(function(modal){

modal.style.display='none';

});

document.body.style.overflow='auto';

}


window.addEventListener('scroll',function(){

const indicator =
document.getElementById('scrollIndicator');

if(window.scrollY > 300){

indicator.classList.add('hidden');

}else{

indicator.classList.remove('hidden');

}

});
